describe('Full-Screen Modals on Small Viewports', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
        cy.viewport('iphone-6'); // Set viewport to a small size
    });

    it('should display the modal in full-screen on small viewports', () => {
        cy.get('.open-modal-button').click(); // Replace with the actual selector for the button that opens the modal
        cy.get('.modal').should('be.visible');
        cy.get('.modal').should('have.css', 'width', '100%');
        cy.get('.modal').should('have.css', 'height', '100%');
    });

    it('should close the modal when the close button is clicked', () => {
        cy.get('.open-modal-button').click(); // Open the modal
        cy.get('.modal .close-button').click(); // Replace with the actual selector for the close button
        cy.get('.modal').should('not.be.visible'); // Verify that the modal is closed
    });
});
